```sql
/* Выбираем молекулы, не являющиеся канцерогенными (label = '-'), */
/* в которых содержится более 5 атомов */
SELECT m."molecule_id"
FROM "molecule" m
JOIN "atom" a ON a."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
GROUP BY m."molecule_id"
HAVING COUNT(a."atom_id") > 5;
