```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди канцерогенных молекул (label = '+') */
SELECT
    /* Доля молекул с водородом среди канцерогенных, умноженная на 100 */
    (SUM(CASE WHEN a."element" = 'h' THEN 1 ELSE 0 END)::numeric
     / COUNT(DISTINCT m."molecule_id")::numeric) * 100.0 AS percentage
FROM "molecule" m
/* Соединяем молекулы с атомами */
JOIN "atom" a
    ON a."molecule_id" = m."molecule_id"
/* Ограничиваем только канцерогенными молекулами */
WHERE m."label" = '+';
```

```sql
/* Вычисляем процент карциногенных молекул среди связей типа '#' (тройные связи) */
SELECT
    /* Процент = (число тройных связей у карциногенных молекул * 100) / общее число связей у карциногенных молекул */
    (SUM(CASE WHEN b."bond_type" = '#' THEN 1 ELSE 0 END) * 100.0)
    / NULLIF(COUNT(b."bond_id"), 0) AS percent
FROM "bond" b
JOIN "molecule" m ON m."molecule_id" = b."molecule_id"
WHERE m."label" = '+';
```

