```sql
/* Calculate the percentage of "incredibly powerful" cards (both Card Kingdom foil and non-foil IDs present) in the Coldsnap set */
SELECT
    /* Numerator: count of incredibly powerful cards in Coldsnap */
    (SUM(CASE WHEN c."cardkingdomfoilid" IS NOT NULL AND c."cardkingdomid" IS NOT NULL THEN 1 ELSE 0 END)::numeric
     /
     /* Denominator: total number of cards in Coldsnap */
     NULLIF(COUNT(*), 0)::numeric) * 100 AS percentage
FROM cards c
JOIN sets s ON c."setcode" = s."code"
WHERE s."name" = 'Coldsnap';
```

