```sql
/* Вычисляем долю пользователей с 0 upvotes среди комментариев со score от 5 до 10 */
SELECT
    /* Процент: числитель — уникальные пользователи с upvotes = 0, знаменатель — все уникальные пользователи */
    (COUNT(DISTINCT CASE WHEN u."upvotes" = 0 THEN c."userid" END)::numeric
     / NULLIF(COUNT(DISTINCT c."userid"), 0)) * 100 AS percentage
FROM "comments" c
JOIN "users" u ON u."id" = c."userid"
WHERE c."score" BETWEEN 5 AND 10;
```

