```sql
/* Вычисляем процент постов с тегом 'r' среди всех постов, опубликованных пользователем Community */
SELECT
    /* Числитель: количество постов Community с тегом 'r' */
    COUNT(DISTINCT CASE WHEN p."tags" LIKE '%<r>%' THEN p."id" END) * 100.0
    /
    /* Знаменатель: общее количество постов Community */
    NULLIF(COUNT(DISTINCT p."id"), 0) AS percentage
FROM "posts" p
/* Соединяем с пользователями, чтобы найти Community */
JOIN "users" u ON u."id" = p."owneruserid"
WHERE u."displayname" = 'Community';
```

