```sql
/* Соотношение между супергероями мужского и женского пола.
   Согласно evidence: male superheroes -> gender = 'Female', female superheroes -> gender = 'Male' */
SELECT
    /* Количество "male superheroes" (gender = 'Female') */
    SUM(CASE WHEN g."gender" = 'Female' THEN 1 ELSE 0 END)::numeric
    /
    /* Количество "female superheroes" (gender = 'Male') */
    NULLIF(SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END), 0)::numeric
    AS ratio
FROM "superhero" s
JOIN "gender" g ON g."id" = s."gender_id";
```

```sql
/* Доля супергероев с alignment = 'Bad' от общего числа, и сколько из них издано Marvel Comics */
SELECT
    /* Процент "плохих" героев от общего числа */
    ROUND(
        100.0 * SUM(CASE WHEN a."alignment" = 'Bad' THEN 1 ELSE 0 END) / COUNT(s."id"),
        2
    ) AS bad_percentage,
    /* Количество "плохих" героев, изданных Marvel Comics */
    SUM(
        CASE WHEN a."alignment" = 'Bad' AND p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END
    ) AS bad_marvel_count
FROM "superhero" s
LEFT JOIN "alignment" a ON a."id" = s."alignment_id"
LEFT JOIN "publisher" p ON p."id" = s."publisher_id";
```

