```sql
/* Вычисляем разницу суммарных расходов по событиям за 2019 и 2020 годы */
SELECT
    /* Сумма spent за 2019 минус сумма spent за 2020 */
    COALESCE(SUM(CASE WHEN EXTRACT(YEAR FROM TO_DATE(e."event_date", 'YYYY-MM-DD')) = 2019 THEN b."spent" END), 0)
    - COALESCE(SUM(CASE WHEN EXTRACT(YEAR FROM TO_DATE(e."event_date", 'YYYY-MM-DD')) = 2020 THEN b."spent" END), 0) AS spent_difference
FROM "budget" b
JOIN "event" e ON b."link_to_event" = e."event_id"
WHERE EXTRACT(YEAR FROM TO_DATE(e."event_date", 'YYYY-MM-DD')) IN (2019, 2020);
```

