/* Доля клиентов, совершивших транзакции 2012-08-25, использующих валюту EUR */
SELECT
    /* Процент клиентов с валютой EUR среди клиентов с транзакциями в указанную дату */
    (COUNT(DISTINCT CASE WHEN c."currency" = 'EUR' THEN t."customerid" END)::numeric
     / NULLIF(COUNT(DISTINCT t."customerid"), 0)) * 100 AS eur_percentage
FROM "transactions_1k" t
JOIN "customers" c ON c."customerid" = t."customerid"
WHERE t."date" = DATE '2012-08-25';
